# expected payload signatures keyed by (group_id, description, payer_email, paid_amount)
def sig_from_payload(p):
    return (p['group_id'], p['description'].strip().lower(), p['payer_email'].strip().lower(), float(p['paid_amount']))

expected_by_sig={}
for p in payloads:
    expected_by_sig[sig_from_payload(p)]=p

mismatches=[]
for eid in created_ids:
    ex=apis.splitwise.show_expense(expense_id=eid, access_token=split_token)
    actual_sig=(ex['group_id'], ex['description'].strip().lower(), ex['payer']['email'].strip().lower(), float(ex['paid_amount']))
    if actual_sig not in expected_by_sig:
        mismatches.append((eid,'no_expected_sig',actual_sig))
        continue
    p=expected_by_sig[actual_sig]
    actual_debtors=sorted([s['debtor']['email'].strip().lower() for s in ex.get('shares',[])])
    expected_debtors=sorted([em.strip().lower() for em in p['debtor_emails']])
    if actual_debtors!=expected_debtors:
        mismatches.append((eid,'debtor_mismatch', actual_debtors, expected_debtors, p['description']))

print('mismatches_count', len(mismatches))
if mismatches:
